<template>
  <el-card shadow="never">
    <template v-if="page==='products'">
      <div class="ops-toolbar"><span>软件类型与正式版本源</span><el-button type="primary" @click="edit('product')">登记软件</el-button></div>
      <el-table :data="data.products"><el-table-column prop="name" label="软件名称"/><el-table-column prop="id" label="编号"/><el-table-column label="类型"><template #default="{row}">{{ kinds[row.kind] }}</template></el-table-column><el-table-column label="GitHub 仓库" min-width="230"><template #default="{row}"><span v-if="row.repository">{{ row.repository }}</span><span v-else class="muted">未关联（可选）</span></template></el-table-column><el-table-column label="版本检查" min-width="200"><template #default="{row}"><span v-if="row.repository">{{ row.check_error || time(row.checked_at) }}</span><span v-else class="muted">仅手动登记版本</span></template></el-table-column><el-table-column label="操作" min-width="160"><template #default="{row}"><el-button link @click="edit('product',row)">编辑</el-button><el-button v-if="row.repository" link type="primary" @click="sync(row.id)">检查正式版</el-button></template></el-table-column></el-table>
    </template>
    <template v-else-if="page==='projects'">
      <div class="ops-toolbar"><span>客户 → 项目 → 实例</span><el-button type="primary" @click="edit('project')">新增项目</el-button></div>
      <el-table :data="data.projects"><el-table-column prop="name" label="项目名称" min-width="140"/><el-table-column prop="customer_name" label="所属客户"/><el-table-column prop="product_name" label="软件"/><el-table-column label="维护期至" min-width="180"><template #default="{row}">{{ time(row.maintenance_until) }}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.effective_status==='ACTIVE'?'success':'danger'">{{ row.effective_status==='ACTIVE'?'维护期内':row.effective_status==='EXPIRED'?'维护已到期':'已暂停' }}</el-tag></template></el-table-column><el-table-column label="默认支付" min-width="170"><template #default="{row}"><span v-if="row.payment_provider_name">{{ row.payment_provider_name }}<br/><small class="muted">{{ row.payment_methods.map(method=>paymentMethodLabels[method]).join(' / ') }}</small></span><span v-else class="muted">未接入在线支付</span></template></el-table-column><el-table-column label="项目金额" min-width="220"><template #default="{row}"><div class="contract-amounts"><span>定金 {{ money(row.deposit_amount_cents) }}</span><span>尾款 {{ money(row.balance_amount_cents) }}</span><strong>合计 {{ money(row.contract_total_cents) }}</strong><small v-if="row.contract_note" class="muted">{{ row.contract_note }}</small></div></template></el-table-column><el-table-column label="到期处理" min-width="170"><template #default="{row}">{{ policies[row.pause_policy] }}</template></el-table-column><el-table-column prop="notification_email" label="通知邮箱" min-width="180"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="edit('project',row)">设置与续期</el-button></template></el-table-column></el-table>
    </template>
    <template v-else-if="page==='mail'">
      <h3>邮箱发信</h3><el-form label-position="top" class="mail-form"><el-form-item label="启用发信"><el-switch v-model="mail.enabled"/></el-form-item><el-form-item label="SMTP 服务器"><el-input v-model="mail.host" placeholder="smtp.example.com"/></el-form-item><el-form-item label="端口"><el-input-number v-model="mail.port" :min="1" :max="65535"/></el-form-item><el-form-item label="连接加密"><el-select v-model="mail.security"><el-option label="SSL/TLS（通常 465）" value="TLS"/><el-option label="STARTTLS（通常 587）" value="STARTTLS"/></el-select></el-form-item><el-form-item label="邮箱账号"><el-input v-model="mail.username"/></el-form-item><el-form-item label="邮箱密码 / 授权码"><el-input v-model="mail.password" type="password" show-password :placeholder="data.mailSettings.hasPassword?'已保存，留空保留原值':'填写邮箱授权码'" autocomplete="new-password"/></el-form-item><el-form-item label="发件邮箱"><el-input v-model="mail.from"/></el-form-item><el-form-item label="发件人名称"><el-input v-model="mail.senderName"/></el-form-item><el-form-item label="运营通知收件邮箱"><el-input v-model="mail.operatorEmail"/></el-form-item><el-button type="primary" :loading="saving" @click="saveMail">保存邮箱配置</el-button><el-button @click="testMail">发送测试邮件</el-button></el-form>
      <p class="muted">项目邮箱与运营邮箱接收维护期到期前 30、7、1 天及当天提醒、续期、状态变更和正式版发布通知。失败邮件自动重试，最多 5 次。</p>
      <el-table :data="data.mailQueue"><el-table-column prop="recipient" label="收件邮箱" min-width="180"/><el-table-column prop="subject" label="主题" min-width="170"/><el-table-column label="状态"><template #default="{row}">{{ mailStatuses[row.status] }}</template></el-table-column><el-table-column prop="attempts" label="尝试次数"/><el-table-column prop="last_error" label="错误代码"/><el-table-column label="创建时间" min-width="180"><template #default="{row}">{{ time(row.created_at) }}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="['FAILED','RETRY'].includes(row.status)" link @click="retry(row.id)">重试</el-button></template></el-table-column></el-table>
    </template>
    <template v-else-if="page==='payments'">
      <div class="ops-toolbar payment-heading"><div><h3>系统支付通道</h3><p class="muted">在系统级维护商户参数。配置并启用后，到“项目管理”为每个项目选择默认接入和支付方式。</p></div><el-tag :type="data.paymentProviders.some(item=>item.enabled)?'success':'info'">{{ data.paymentProviders.some(item=>item.enabled)?'已有可用支付通道':'尚未启用支付通道' }}</el-tag></div>
      <el-card v-for="provider in data.paymentProviders" :key="provider.id" shadow="never" class="payment-card">
        <template #header><div class="payment-card-title"><div><strong>{{ provider.name }}</strong><p>{{ provider.description }}</p></div><el-switch v-model="paymentForms[provider.id].enabled" active-text="系统启用" inactive-text="停用"/></div></template>
        <el-alert v-if="paymentForms[provider.id]?.enabled" title="启用后，项目可把此通道设为默认支付接入。项目参数不会复制商户密钥；实例同步只获得通道名称和支付方式。" type="success" :closable="false"/>
        <el-form label-position="top" class="payment-form">
          <el-form-item v-for="field in provider.config_schema" :key="field.key" :label="field.label" :required="field.required"><el-input v-model="paymentForms[provider.id].config[field.key]" :type="field.type==='password'?'password':'text'" :show-password="field.type==='password'" autocomplete="new-password" :placeholder="field.type==='password'&&provider.secretsSet?'已配置，留空保留原值':field.required?'必填':'选填'"/></el-form-item>
          <el-form-item label="系统允许的支付方式"><el-checkbox-group v-model="paymentForms[provider.id].methods"><el-checkbox v-for="method in paymentMethods" :key="method" :value="method">{{ paymentMethodLabels[method] }}</el-checkbox></el-checkbox-group></el-form-item>
          <el-button type="primary" :loading="saving" @click="savePayment(provider)">保存支付通道</el-button>
        </el-form>
      </el-card>
      <h3 class="subheading">项目支付接入</h3><p class="muted">这里展示每个项目已选择的默认支付接入；修改入口在项目管理的项目设置中。</p>
      <el-table :data="data.projects"><el-table-column prop="name" label="项目"/><el-table-column prop="customer_name" label="客户"/><el-table-column label="支付通道"><template #default="{row}"><span v-if="row.payment_provider_name">{{ row.payment_provider_name }} <el-tag v-if="!row.payment_provider_enabled" size="small" type="warning">系统已停用</el-tag></span><span v-else class="muted">未接入</span></template></el-table-column><el-table-column label="默认方式"><template #default="{row}">{{ row.payment_methods.map(method=>paymentMethodLabels[method]).join(' / ') || '—' }}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="edit('project',row)">设置默认接入</el-button></template></el-table-column></el-table>
    </template>
    <template v-else-if="page==='releases'">
      <div class="ops-toolbar"><el-select v-model="productId"><el-option v-for="product in data.products" :key="product.id" :value="product.id" :label="product.name+(product.repository?' · '+product.repository:' · 未关联仓库')"/></el-select><el-button type="primary" :loading="syncing" :disabled="!product?.repository" @click="sync(productId)">连接 GitHub 检查正式版</el-button></div><el-alert v-if="product&&!product.repository" title="该软件未关联 GitHub；仍可登记项目和授权，版本目录可手动配置或后续补充仓库。" type="info" :closable="false"/>
      <el-alert v-if="product?.check_error" :title="product.check_error" type="warning" :closable="false"/><p class="muted">最后成功检查：{{ time(product?.checked_at) }}。只同步正式 Release，客户端按自身版本显示所有较新版本。</p>
      <el-table :data="data.releases.filter(row=>row.product_id===productId)"><el-table-column prop="version" label="正式版本"/><el-table-column prop="notes" label="更新说明" min-width="250" show-overflow-tooltip/><el-table-column label="更新项"><template #default="{row}">{{ row.items.length }} 项</template></el-table-column><el-table-column label="发布来源"><template #default="{row}">{{ row.origin==='GITHUB'?'GitHub 正式版':'手动登记' }}</template></el-table-column><el-table-column label="操作" min-width="200"><template #default="{row}"><el-button link type="primary" @click="editItems(row)">配置可选内容</el-button><a :href="row.source_url" target="_blank" rel="noopener noreferrer">Release</a></template></el-table-column></el-table>
    </template>
  </el-card>
  <el-dialog v-model="visible" :title="kind==='product'?'登记软件':'项目设置与续期'" width="min(620px,94vw)"><el-form label-position="top">
    <template v-if="kind==='product'"><el-form-item label="软件编号"><el-input v-model="form.id" :disabled="editing" placeholder="如 detla / shop / booking"/></el-form-item><el-form-item label="软件名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="类型"><el-select v-model="form.kind"><el-option v-for="(label,value) in kinds" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="GitHub 仓库（可选）"><el-input v-model="form.repository" placeholder="不用 GitHub 可留空；需要自动检查版本时填写 owner/repository"/></el-form-item><el-form-item label="私有仓库只读令牌（可选）"><el-input v-model="form.githubToken" type="password" show-password autocomplete="new-password" :placeholder="form.token_configured?'已配置，留空保留原令牌':'不用 GitHub 可留空；私有仓库填写 Fine-grained 令牌'"/></el-form-item><p class="muted">不使用 GitHub 自动检查时，仓库和令牌都留空即可。配置私有仓库时，仅选择该仓库并授予 Contents: Read-only；令牌保存后不回显。</p></template>
    <template v-else><el-form-item label="所属客户"><el-select v-model="form.customerId" :disabled="editing"><el-option v-for="customer in data.customers" :key="customer.id" :value="customer.id" :label="customer.name"/></el-select></el-form-item><el-form-item label="所用软件"><el-select v-model="form.productId" :disabled="editing"><el-option v-for="product in data.products" :key="product.id" :value="product.id" :label="product.name"/></el-select></el-form-item><el-form-item label="项目名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="维护期至（即授权到期时间）"><el-date-picker v-model="form.until" type="datetime" :clearable="false" format="YYYY-MM-DD HH:mm:ss"/></el-form-item><div class="amount-row"><el-form-item label="项目定金（元）"><el-input v-model="form.depositYuan" inputmode="decimal" placeholder="未填写"><template #append>元</template></el-input></el-form-item><el-form-item label="项目尾款（元）"><el-input v-model="form.balanceYuan" inputmode="decimal" placeholder="未填写"><template #append>元</template></el-input></el-form-item></div><el-form-item label="项目收款备注"><el-input v-model="form.contractNote" type="textarea" :rows="2" maxlength="500" show-word-limit placeholder="例如：定金已收，尾款验收后支付"/><span class="muted">仅记录项目商务金额和备注，不会触发扣款或改变授权状态。</span></el-form-item><el-form-item label="默认支付接入"><el-select v-model="form.paymentProvider" clearable placeholder="不接入在线支付"><el-option label="不接入在线支付" value=""/><el-option v-for="provider in data.paymentProviders" :key="provider.id" :value="provider.id" :disabled="!provider.enabled" :label="provider.name+(provider.enabled?'':'（系统未启用）')"/></el-select><span class="muted">商户参数在“系统设置 → 支付设置”统一维护。未启用的通道不能选择。</span></el-form-item><el-form-item v-if="form.paymentProvider" label="项目默认支付方式"><el-select v-model="form.paymentMethods" multiple><el-option v-for="method in paymentMethodsFor(form.paymentProvider)" :key="method" :value="method" :label="paymentMethodLabels[method]"/></el-select></el-form-item><el-form-item label="到期暂停策略"><el-select v-model="form.pausePolicy"><el-option v-for="(label,value) in policies" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-alert v-if="form.pausePolicy==='PENDING'" title="在途订单处理待确认；确认策略后才会启用自动业务暂停。" type="warning" :closable="false"/><el-form-item label="项目状态"><el-select v-model="form.status"><el-option label="启用" value="ACTIVE"/><el-option label="手动暂停" value="PAUSED"/></el-select></el-form-item><el-form-item label="项目通知邮箱"><el-input v-model="form.notificationEmail" placeholder="客户接收重要通知的邮箱"/></el-form-item><p class="muted">续期会同步更新本项目所有实例的授权，到期暂停不删除业务数据。</p></template>
  </el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
  <el-dialog v-model="itemsVisible" :title="'配置 '+release?.version+' 更新内容'" width="min(850px,96vw)"><p class="muted">属于同一程序包的内容会作为关联更新一起安装。安全修复和必要迁移请标记为必须更新。</p><div v-for="(item,index) in items" :key="index" class="update-item"><el-input v-model="item.id" placeholder="内容编号（英文字母）"/><el-input v-model="item.name" placeholder="内容名称"/><el-input v-model="item.description" placeholder="变更说明"/><el-select v-model="item.component"><el-option label="后端" value="backend"/><el-option label="管理后台" value="admin"/><el-option label="H5" value="h5"/></el-select><el-select v-model="item.requires" multiple clearable placeholder="依赖的更新内容"><el-option v-for="dependency in items.filter(candidate=>candidate.id && candidate.id!==item.id)" :key="dependency.id" :value="dependency.id" :label="dependency.name || dependency.id"/></el-select><el-select v-model="item.featureId" clearable placeholder="可选：需要购买的功能模块"><el-option v-for="module in data.modules.filter(module=>module.product_id===release.product_id)" :key="module.id" :value="module.id" :label="module.name"/></el-select><el-checkbox v-model="item.required">必须更新</el-checkbox><el-button type="danger" text @click="items.splice(index,1)">删除</el-button></div><el-button @click="items.push({id:'',name:'',description:'',component:'backend',required:false,requires:[]})">添加更新内容</el-button><template #footer><el-button @click="itemsVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveItems">保存</el-button></template></el-dialog>
</template>
<script setup>
import {computed,reactive,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
const props=defineProps({page:String,data:Object,api:Function}),emit=defineEmits(['refresh'])
const kinds={WEB:'网页系统',H5:'H5 / 移动网页',MINIAPP:'小程序项目',OTHER:'其他项目'},policies={PENDING:'待确认',STOP_ALL:'暂停全部业务请求',FINISH_EXISTING:'停止新业务，允许在途完成'},mailStatuses={PENDING:'待发送',RETRY:'等待重试',SENT:'已发送',FAILED:'发送失败'},paymentMethods=['H5','JSAPI','NATIVE','APP'],paymentMethodLabels={H5:'H5 网页支付',JSAPI:'JSAPI 公众号支付',NATIVE:'Native 扫码支付',APP:'App 支付'}
const visible=ref(false),kind=ref('product'),editing=ref(false),form=reactive({}),saving=ref(false),syncing=ref(false),mail=reactive({}),paymentForms=reactive({}),productId=ref('detla'),product=computed(()=>props.data.products.find(row=>row.id===productId.value)),itemsVisible=ref(false),items=ref([]),release=ref(null)
watch(()=>props.data.mailSettings,value=>Object.assign(mail,{security:'TLS',port:465,senderName:'沧烁授权中心',...value,password:''}),{immediate:true})
watch(()=>props.data.paymentProviders,list=>{for(const provider of list||[])paymentForms[provider.id]={...provider,config:{...(provider.config||{})},methods:[...(provider.methods||[])]}},{immediate:true})
const time=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'尚未检查'
const money=value=>value==null?'未填写':'¥'+(Number(value)/100).toFixed(2)
function yuanToCents(value,label){const raw=String(value??'').trim();if(!raw)return null;if(!/^(?:0|[1-9]\d{0,8})(?:\.\d{1,2})?$/.test(raw))throw new Error(label+'须为最多两位小数的非负金额');return Math.round(Number(raw)*100)}
function edit(type,row={}){kind.value=type;editing.value=!!row.id;Object.keys(form).forEach(key=>delete form[key]);Object.assign(form,{kind:'WEB',status:'ACTIVE',...row,pausePolicy:row.pause_policy||'PENDING',customerId:row.customer_id,productId:row.product_id||'detla',paymentProvider:row.payment_provider||'',paymentMethods:[...(row.payment_methods||[])],depositYuan:row.deposit_amount_cents==null?'':(row.deposit_amount_cents/100).toFixed(2),balanceYuan:row.balance_amount_cents==null?'':(row.balance_amount_cents/100).toFixed(2),contractNote:row.contract_note||'',notificationEmail:row.notification_email||'',until:row.maintenance_until?new Date(row.maintenance_until):new Date(Date.now()+365*86400000)});visible.value=true}
async function run(action){saving.value=true;try{await action();emit('refresh');ElMessage.success('已保存')}catch(error){ElMessage.error(error.message)}finally{saving.value=false}}
function save(){return run(async()=>{const body={...form,depositAmountCents:yuanToCents(form.depositYuan,'项目定金'),balanceAmountCents:yuanToCents(form.balanceYuan,'项目尾款'),contractNote:form.contractNote||'',maintenanceUntil:form.until.toISOString()};await props.api(kind.value==='product'?(editing.value?'/products/'+form.id:'/products'):(editing.value?'/projects/'+form.id:'/projects'),{method:editing.value?'PUT':'POST',body});visible.value=false})}
function saveMail(){return run(()=>props.api('/mail/settings',{method:'PUT',body:mail}))}
function savePayment(provider){return run(()=>props.api('/payments/'+provider.id,{method:'PUT',body:{enabled:paymentForms[provider.id].enabled,config:paymentForms[provider.id].config,methods:paymentForms[provider.id].methods}}))}
function paymentMethodsFor(id){return props.data.paymentProviders.find(provider=>provider.id===id)?.methods||[]}
async function testMail(){try{const {value}=await ElMessageBox.prompt('填写测试邮件收件邮箱，使用已保存的 SMTP 配置。','发送测试邮件',{inputValue:mail.operatorEmail||''});await props.api('/mail/test',{method:'POST',body:{recipient:value}});emit('refresh');ElMessage.success('测试邮件已进入发送队列')}catch(error){if(error?.message)ElMessage.error(error.message)}}
async function sync(id){syncing.value=true;try{await props.api('/products/'+id+'/sync',{method:'POST',body:{}});emit('refresh');ElMessage.success('GitHub 正式版已同步')}catch(error){ElMessage.error(error.message);emit('refresh')}finally{syncing.value=false}}
function retry(id){return run(()=>props.api('/mail/'+id+'/retry',{method:'POST',body:{}}))}
function editItems(row){release.value=row;items.value=JSON.parse(JSON.stringify(row.items));itemsVisible.value=true}
function saveItems(){return run(async()=>{await props.api(`/products/${release.value.product_id}/releases/${encodeURIComponent(release.value.version)}/items`,{method:'PUT',body:{items:items.value}});itemsVisible.value=false})}
</script>
<style scoped>.ops-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.ops-toolbar .el-select{max-width:480px}.mail-form,.payment-form{max-width:720px}.amount-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.contract-amounts{display:flex;flex-direction:column;gap:3px;font-size:12px}.contract-amounts strong{color:#253247}.payment-heading h3,.subheading{margin:0 0 6px;font-size:18px}.payment-heading p,.payment-card-title p{margin:0}.payment-card{margin-bottom:18px}.payment-card-title{display:flex;justify-content:space-between;align-items:center;gap:18px}.subheading{margin-top:28px}.update-item{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:16px 0;border-bottom:1px solid #eee}.update-item .el-select{width:100%}@media(max-width:720px){.payment-card-title,.ops-toolbar{align-items:flex-start;flex-direction:column}.payment-card-title .el-switch{margin-top:6px}}</style>
